ureau/Service/Functional Division/School: <?= $esc($sectionName); ?><?= $effectivity ? ' &nbsp; | &nbsp; Effective ' . $esc(date('F j, Y', strtotime($effectivity))) : ''; ?></div><h3>B.&nbsp;&nbsp; SWOT</h3><table><colgroup><col style="width:6%"><col style="width:47%"><col style="width:47%"></colgroup><tr><td></td><th class="head-strength">STRENGTHS</th><th class="head-weakness">WEAKNESS</th></tr><tr><td class="label">Internal</td><td class="items"><ol><?php foreach($groups['Strength'] as $e): ?><li><?= $esc($e->description); ?></li><?php endforeach;?></ol></td><td class="items"><ol><?php foreach($groups['Weakness'] as $e): ?><li><?= $esc($e->description); ?></li><?php endforeach;?></ol></td></tr><tr><td></td><th class="head-opportunity">OPPORTUNITIES</th><th class="head-threat">THREATS</th></tr><tr><td class="label">External</td><td class="items"><ol><?php foreach($groups['Opportunity'] as $e): ?><li><?= $esc($e->description); ?></li><?php endforeach;?></ol></td><td class="items"><ol><?php foreach($groups['Threat'] as $e): ?><li><?= $esc($e->description); ?></li><?php endforeach;?></ol></td></tr></table><div class="signatures"><div class="signature">Prepared by:<div class="line"><?= $esc($preparedBy); ?></div>Process Owner</div><div class="signature">Approved by:<div class="line">&nbsp;</div>Division Chief / Authorized Approver</div></div><?php if($settings && $settings->footer_file): ?><img class="footer" src="<?= $esc($asset($settings->footer_file)); ?>" alt="Report footer"><?php endif;?></body></html>
